int g;                          // file scope, static duration, external linkage
static int hidden;              // file scope, static duration, internal linkage

void f(void) {
    auto int a = 1;             // block scope, automatic (auto is redundant)
    static int calls;           // block scope, static duration, starts at 0
    register int i;             // block scope, automatic, hint: keep in a register
    extern int g;               // refers to the global g above
    calls++;
}

#include <stdio.h>

void counter(void) {
    int a = 0;            // new object each call, reset to 0
    static int s = 0;     // one object for the whole run, initialized once
    a++;
    s++;
    printf("a=%d s=%d\n", a, s);
}

int main(void) {
    counter();            // a=1 s=1
    counter();            // a=1 s=2
    counter();            // a=1 s=3
    return 0;
}

int sum(int n) {
    auto int total = 0;           // identical to: int total = 0;
    for (int i = 1; i <= n; i++)  // i is automatic too, scoped to the loop
        total += i;
    return total;
}

const char *day_name(int d) {
    static const char *names[] = {"Sun","Mon","Tue","Wed","Thu","Fri","Sat"};
    return names[d % 7];          // pointer stays valid after return
}
int next_id(void) {
    static int id = 100;          // starts at 100 once, then 101, 102, ...
    return ++id;
}

